C/README.md:1: # Room bookings
C/README.md:2: 
C/README.md:3: A small meeting-room booking app: a Node.js HTTP server (`server.mjs`, no dependencies)
C/README.md:4: with a JSON API and a browser page. Data is kept in one JSON file.
C/README.md:5: 
C/README.md:6: ## Usage
C/README.md:7: 
C/README.md:8: ```sh
C/README.md:9: npm start                              # same as: node server.mjs
C/README.md:10: PORT=8080 DATA_FILE=data/rooms.json node server.mjs
C/README.md:11: ```
C/README.md:12: 
C/README.md:13: Then open the printed address (default `http://127.0.0.1:3000`).
C/README.md:14: 
C/README.md:15: - `PORT`: port to listen on (127.0.0.1 only). Default `3000`; `0` picks a free port.
C/README.md:16: - `DATA_FILE`: JSON data file, relative to the current directory. Default `bookings.json`.
C/README.md:17:   A missing file means no bookings yet. Its folder is never created.
C/README.md:18: 
C/README.md:19: ## API
C/README.md:20: 
C/README.md:21: | Method & path               | Result                                                   |
C/README.md:22: |-----------------------------|----------------------------------------------------------|
C/README.md:23: | `GET /api/rooms`            | `{"rooms": ["Aurora", "Borealis", "Cosmos"]}`            |
C/README.md:24: | `GET /api/bookings[?date=]` | `{"bookings": [...]}`, sorted by date, start and room     |
C/README.md:25: | `POST /api/bookings`        | JSON body `room`, `title`, `date`, `start`, `end`  201  |
C/README.md:26: | `DELETE /api/bookings/<id>` | 204, or 404 `booking not found`                          |
C/README.md:27: 
C/README.md:28: Errors are `{"error": "<message>"}` (400, 404, 405, 409, 413, 415 or 500).
C/README.md:29: 
C/README.md:30: ## Tests
C/README.md:31: 
C/README.md:32: ```sh
C/README.md:33: npm test
C/README.md:34: ```

364: async function handle(req, res) {
365:   const body = await readBody(req);
366:   const target = req.url;
367:   const q = target.indexOf('?');
368:   const pathname = q === -1 ? target : target.slice(0, q);
369:   const query = q === -1 ? '' : target.slice(q + 1);
370:   const method = req.method;
371:   const notAllowed = () => new HttpError(405, 'method not allowed');
372: 
373:   if (pathname === '/api/rooms') {
374:     if (method !== 'GET') throw notAllowed();
375:     return sendJson(res, 200, { rooms: ROOMS });
376:   }
377:   if (pathname === '/api/bookings') {
378:     if (method === 'GET') return sendJson(res, 200, { bookings: listBookings(query) });
379:     if (method === 'POST') return sendJson(res, 201, createBooking(req, body));
380:     throw notAllowed();
381:   }
382:   if (pathname.startsWith('/api/bookings/')) {
383:     const id = pathname.slice('/api/bookings/'.length);
384:     if (id === '' || id.includes('/')) throw new HttpError(404, 'not found');
385:     if (method !== 'DELETE') throw notAllowed();
386:     deleteBooking(id);
387:     res.writeHead(204);
388:     return res.end();
389:   }
390:   if (pathname === '/') {
391:     if (method !== 'GET') throw notAllowed();
392:     return sendText(res, 'text/html; charset=utf-8', PAGE);
393:   }
394:   if (pathname === '/app.js') {
395:     if (method !== 'GET') throw notAllowed();
396:     return sendText(res, 'text/javascript; charset=utf-8', SCRIPT);
397:   }
398:   throw new HttpError(404, 'not found');
399: }
400: 
401: const server = http.createServer((req, res) => {
402:   handle(req, res).catch((err) => {
403:     if (res.headersSent || res.destroyed) return;
404:     if (err instanceof HttpError) sendJson(res, err.status, { error: err.message });
405:     else sendJson(res, 500, { error: 'internal error' });
406:   });
407: });
408: 
409: server.on('error', (err) => fail(`cannot listen on port ${port}: ${err.message}`));
410: server.listen(port, '127.0.0.1', () => {
411:   process.stdout.write(`listening on http://127.0.0.1:${server.address().port}\n`);
412: });
